"""The retained 9B scalar witness must not lose a sender or its O(1) VJP."""
import pytest
import torch

import tide.allocation as allocation
from tide.allocation import _quad_face_bounds, allocate


# Original region4 submission: call2/region43/node817/sample5/time509.
# These are exact FP32 input images, not scores regenerated by a new model.
SCORES = [
    .6103276014328003, 1.0490667819976807, -.9901294708251953, 1.5498405694961548,
    -1.2891095876693726, .8287231922149658, -1.2566776275634766, .0813366174697876,
    .4828444719314575, .6775972247123718, .36453092098236084, .52934730052948,
    .49178850650787354, -1.9481600522994995, -.8216829299926758, -.2624695599079132,
    .5102242231369019, -.3350093960762024, .15582633018493652, -1.1064841747283936,
    1.7677510976791382, -.5181277990341187, -1.210545539855957, -1.713375210762024,
    -.9058512449264526, .6424201726913452, -.16327108442783356, 1.3303823471069336,
    .12578630447387695, .6799108982086182, -.10282532870769501, -.4351327419281006,
]
RECEIVED = [
    .6754063367843628, .4046550989151001, 0., 0., 0., 1.0930339097976685, 0., .7254058122634888,
    .37227189540863037, .37227189540863037, .5, .25, .25, .25, 0., .0061540305614471436,
    .7468140721321106, 0., .5155658721923828, .10724839568138123, 1.1072484254837036, .25,
    0., .19913041591644287, 1.6176259517669678, .7744077444076538, 1.629854679107666,
    .6785976886749268, 0., 0., .36834391951560974, .6183439493179321,
]


def recorded_row(*, corner=False, contiguous=False):
    score = torch.tensor(SCORES, dtype=torch.float32)
    if corner:
        # One representable step makes 1+2*s1-s20-s27 exactly zero.
        score[27] = torch.nextafter(score[27], score.new_tensor(torch.inf))
    receive = torch.tensor(RECEIVED, dtype=torch.float32)
    # Match original node-major storage before allocation's [B,L,node] view.
    # Repeating only the retained row avoids a large or device-owned fixture.
    score = score[:, None, None].expand(32, 8, 32).clone().permute(1, 2, 0)
    receive = receive[:, None, None].expand(32, 8, 32).clone().permute(1, 2, 0)
    if contiguous:
        score, receive = score.contiguous(), receive.contiguous()
    return score, receive


@pytest.mark.parametrize("corner", [False, True])
@pytest.mark.parametrize("contiguous", [False, True])
def test_recorded_shape_sender_and_score_vjp_against_independent_three_node_formula(corner, contiguous):
    scores, received = recorded_row(corner=corner, contiguous=contiguous)
    assert scores.shape == (8, 32, 32)
    assert scores.stride() == ((1024, 32, 1) if contiguous else (32, 1, 256))
    scores.requires_grad_()
    w, mu = received.clamp(0, 1), (2*received).clamp(0, 1)
    result = allocate(scores, w, mu, torch.zeros_like(mu), mu, 1.)
    row = scores.detach()[5, 20].double()
    # This row has no active caps/floors on {1,20,27}. The strict convex optimum
    # on that face gives this independent numerator, without a root solver.
    numerator = 1+2*row[1]-row[20]-row[27]
    assert numerator == (0 if corner else 2**-23)
    wanted = numerator/3
    assert bool(result[5, 20, 1] > 0) is (not corner)
    torch.testing.assert_close(result[5, 20, 1].double(), wanted, atol=1e-6, rtol=2e-3)
    support = result[5, 20] > 0
    assert support.nonzero().flatten().tolist() == ([20, 27] if corner else [1, 20, 27])
    score_grad = torch.autograd.grad(result[5, 20, 1], scores)[0]
    expected = torch.zeros_like(scores)
    if not corner:
        expected[5, 20, [1, 20, 27]] = expected.new_tensor([1., 0., 0.])-1/3
    torch.testing.assert_close(score_grad, expected, atol=0, rtol=0)


def test_wrong_face_is_rejected_despite_exact_total_and_uses_existing_fp32_fallback(monkeypatch):
    scores, received = recorded_row()
    mu = (2*received).clamp(0, 1); lower = torch.zeros_like(mu)
    shifted = scores-torch.where(mu > 0, scores, -torch.inf).amax(-1, keepdim=True)
    target = torch.ones_like(shifted[..., :1])
    preliminary, valid = allocation._quad_sorted(shifted, lower, mu, target)
    assert preliminary[5, 20].sum() == 1
    assert preliminary[5, 20, 1] == 0 and not valid[5, 20, 0]
    called = []
    original = allocation._bisect
    def fallback(*args):
        called.append((args[0].dtype, args[0].device, args[4].clone()))
        return original(*args)
    monkeypatch.setattr(allocation, "_bisect", fallback)
    result = allocate(scores, received.clamp(0, 1), mu, lower, mu, 1.)
    assert len(called) == 1
    assert called[0][:2] == (torch.float32, torch.device("cpu"))
    assert called[0][2][5, 20, 0] and result[5, 20, 1] > 0


@pytest.mark.parametrize("scores,lower,upper,target,control,valid", [
    # Genuine lower, nonzero floor, upper and fixed-through faces.
    ([.6, .4, -1.], [0., 0., 0.], [1., 1., 1.], 1., [.6, .4, 0.], True),
    ([.2, .9, .4], [.25, 0., 0.], [1., 1., 1.], 1., [.25, .625, .125], True),
    ([.8, .7, .4], [0., 0., 0.], [.4, 1., 1.], 1., [.4, .45, .15], True),
    ([1e6, .6, .4], [.4, 0., 0.], [.4, 1., 1.], 1., [.4, .4, .2], True),
    # An exhausted total does not by itself certify an incorrectly capped node.
    ([.5, .7, .4], [0., 0., 0.], [.4, 1., 1.], 1., [.4, .45, .15], False),
    # Empty interior: flat interval, exact singleton interval, impossible face,
    # and all-fixed coordinates with irrelevant large scores.
    ([0., 2.], [0., 0.], [1., 1.], 1., [0., 1.], True),
    ([0., 1.], [0., 0.], [1., 1.], 1., [0., 1.], True),
    ([2., 0.], [0., 0.], [1., 1.], 1., [0., 1.], False),
    ([1e10, -1e10], [.2, .3], [.2, .3], .5, [.2, .3], True),
])
@pytest.mark.parametrize("dtype", [torch.float32, torch.float64])
def test_final_lower_upper_fixed_and_empty_interior_bounds(scores, lower, upper, target, control, valid, dtype):
    tensors = [torch.tensor(value, dtype=dtype) for value in (scores, lower, upper, [target], control)]
    assert bool(_quad_face_bounds(*tensors)) is valid
